def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(value, default=(0, 0)):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            a, b = value[0], value[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return int(a), int(b)
        return default

    def nearest(targets, sx, sy):
        best = None
        best_d = None
        for t in targets or []:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = abs(tx - sx) + abs(ty - sy)
            if best_d is None or d < best_d:
                best = (tx, ty)
                best_d = d
        return best

    def step_toward(sx, sy, tx, ty):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def step_away(sx, sy, tx, ty):
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"), (0, 0))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0)
    gh = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(sx, sy, ox, oy)
        corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        best_corner = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return step_toward(sx, sy, best_corner[0], best_corner[1])

    if env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or observation.get("frontier_cells")
            or observation.get("targets")
            or []
        )
        target = nearest(targets, sx, sy)
        if target is not None:
            return step_toward(sx, sy, target[0], target[1])
        return step_away(sx, sy, ox, oy)

    resources = (
        observation.get("resources")
        or observation.get("resource_positions")
        or observation.get("unclaimed_resources")
        or []
    )
    target = nearest(resources, sx, sy)
    if target is not None:
        return step_toward(sx, sy, target[0], target[1])

    return step_away(sx, sy, ox, oy)

